CREATE TABLE posting (id INTEGER PRIMARY KEY, jurnal_id INTEGER NOT NULL, buku_id INTEGER NOT NULL, jumlah INTEGER NOT NULL, dibuat TEXT NOT NULL);
WITH RECURSIVE g(x) AS (SELECT 1 UNION ALL SELECT x + 1 FROM g WHERE x < 100000)
INSERT INTO posting SELECT x, 1 + x / 2, 1 + (x % 1000), CASE WHEN x % 2 = 0 THEN -25000 ELSE 25000 END, datetime('2026-01-01', '+' || (x * 300) || ' seconds') FROM g;
